from typing import Any

from datetime import datetime


class Execution:
    name: str = "validate_clean_data"
    description: str = "Validates required sales fields, rejects invalid rows, and computes order totals."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "records", "type": list},
    ]

    outputs: list[dict] = [
        {"name": "clean_records", "type": list},
        {"name": "rejected_count", "type": float},
        {"name": "rejected_details", "type": list},
    ]

    parameters: dict = {
        "min_quantity": {"type": float, "default": 1},
    }

    REQUIRED = (
        "order_id",
        "customer_id",
        "product",
        "quantity",
        "unit_price",
        "order_date",
        "region",
    )
    REGIONS = ("North", "South", "East", "West")

    def _validate(self, record: Any, min_quantity: int) -> str:
        if not isinstance(record, dict):
            return "record is not an object"
        for field in self.REQUIRED:
            if field not in record:
                return "missing field: %s" % field
            value = record[field]
            if isinstance(value, str) and not value.strip():
                return "empty field: %s" % field
            if value is None:
                return "empty field: %s" % field

        try:
            quantity = int(record["quantity"])
        except (TypeError, ValueError):
            return "quantity is not an integer"
        if quantity < min_quantity:
            return "quantity below minimum (%s)" % min_quantity

        try:
            unit_price = float(record["unit_price"])
        except (TypeError, ValueError):
            return "unit_price is not numeric"
        if unit_price <= 0:
            return "unit_price must be positive"

        try:
            datetime.strptime(str(record["order_date"]), "%Y-%m-%d")
        except (TypeError, ValueError):
            return "order_date is not ISO YYYY-MM-DD"

        if str(record["region"]) not in self.REGIONS:
            return "unknown region: %s" % record["region"]

        return ""

    def run(self, inputs, parameters, context):
        records = inputs.get("records") or []
        min_quantity = int(parameters.get("min_quantity", 1))

        clean_records: list[dict] = []
        rejected_details: list[dict] = []

        for record in records:
            reason = self._validate(record, min_quantity)
            if reason:
                rejected_details.append(
                    {
                        "order_id": record.get("order_id") if isinstance(record, dict) else None,
                        "reason": reason,
                    }
                )
                continue

            quantity = int(record["quantity"])
            unit_price = float(record["unit_price"])
            cleaned = dict(record)
            cleaned["quantity"] = quantity
            cleaned["unit_price"] = round(unit_price, 2)
            cleaned["total_amount"] = round(quantity * unit_price, 2)
            clean_records.append(cleaned)

        return {
            "clean_records": clean_records,
            "rejected_count": len(rejected_details),
            "rejected_details": rejected_details,
        }

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

