class Execution:
    name: str = "revenue_analysis"
    description: str = "Computes revenue totals, regional breakdown, and product performance."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "clean_records", "type": list},
    ]

    outputs: list[dict] = [
        {"name": "revenue_metrics", "type": dict},
    ]

    parameters: dict = {}

    def run(self, inputs, parameters, context):
        records = inputs.get("clean_records") or []

        total_revenue = 0.0
        order_count = 0
        revenue_by_region: dict = {}
        product_revenue: dict = {}
        product_units: dict = {}

        for record in records:
            amount = float(record.get("total_amount", 0.0))
            region = str(record.get("region", "Unknown"))
            product = str(record.get("product", "Unknown"))

            total_revenue += amount
            order_count += 1
            revenue_by_region[region] = round(revenue_by_region.get(region, 0.0) + amount, 2)
            product_revenue[product] = round(product_revenue.get(product, 0.0) + amount, 2)
            product_units[product] = product_units.get(product, 0) + int(record.get("quantity", 0))

        average_order_value = round(total_revenue / order_count, 2) if order_count else 0.0
        best_selling_product = max(product_units, key=product_units.get) if product_units else None
        top_revenue_product = max(product_revenue, key=product_revenue.get) if product_revenue else None

        return {
            "revenue_metrics": {
                "total_revenue": round(total_revenue, 2),
                "average_order_value": average_order_value,
                "total_orders": order_count,
                "revenue_by_region": revenue_by_region,
                "best_selling_product": best_selling_product,
                "best_selling_units": product_units.get(best_selling_product, 0) if best_selling_product else 0,
                "top_revenue_product": top_revenue_product,
                "top_revenue_amount": product_revenue.get(top_revenue_product, 0.0) if top_revenue_product else 0.0,
                "product_units": product_units,
                "product_revenue": product_revenue,
            }
        }

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

