class Execution:
    name: str = "customer_analysis"
    description: str = "Computes customer counts, repeat behaviour, and spending segments."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "clean_records", "type": list},
    ]

    outputs: list[dict] = [
        {"name": "customer_metrics", "type": dict},
    ]

    parameters: dict = {
        "high_value_threshold": {"type": float, "default": 2000},
        "medium_value_threshold": {"type": float, "default": 800},
    }

    def run(self, inputs, parameters, context):
        records = inputs.get("clean_records") or []
        high_threshold = float(parameters.get("high_value_threshold", 2000))
        medium_threshold = float(parameters.get("medium_value_threshold", 800))

        spending: dict = {}
        orders: dict = {}
        for record in records:
            customer = str(record.get("customer_id", "UNKNOWN"))
            amount = float(record.get("total_amount", 0.0))
            spending[customer] = round(spending.get(customer, 0.0) + amount, 2)
            orders[customer] = orders.get(customer, 0) + 1

        unique_customers = len(spending)
        repeat_customers = sum(1 for count in orders.values() if count > 1)
        average_spending = (
            round(sum(spending.values()) / unique_customers, 2) if unique_customers else 0.0
        )

        segments = {"high": [], "medium": [], "low": []}
        for customer, total in sorted(spending.items(), key=lambda item: item[1], reverse=True):
            if total >= high_threshold:
                segments["high"].append(customer)
            elif total >= medium_threshold:
                segments["medium"].append(customer)
            else:
                segments["low"].append(customer)

        top_customers = sorted(spending.items(), key=lambda item: item[1], reverse=True)[:3]

        return {
            "customer_metrics": {
                "total_unique_customers": unique_customers,
                "repeat_customers": repeat_customers,
                "repeat_rate": round(repeat_customers / unique_customers, 2) if unique_customers else 0.0,
                "average_spending_per_customer": average_spending,
                "segment_thresholds": {"high": high_threshold, "medium": medium_threshold},
                "segment_counts": {
                    "high": len(segments["high"]),
                    "medium": len(segments["medium"]),
                    "low": len(segments["low"]),
                },
                "customer_spending": spending,
                "customer_orders": orders,
                "top_customers": [{"customer_id": c, "total_spend": t} for c, t in top_customers],
            }
        }

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

