class Execution:
    name: str = "business_insights"
    description: str = "Derives business insights from revenue and customer analysis outputs."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "revenue_metrics", "type": dict},
        {"name": "customer_metrics", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "insights", "type": list},
    ]

    parameters: dict = {}

    def run(self, inputs, parameters, context):
        revenue = inputs.get("revenue_metrics") or {}
        customers = inputs.get("customer_metrics") or {}

        total_revenue = float(revenue.get("total_revenue", 0.0))
        orders = int(revenue.get("total_orders", 0))
        aov = float(revenue.get("average_order_value", 0.0))
        by_region = revenue.get("revenue_by_region") or {}
        best_seller = revenue.get("best_selling_product")
        best_units = int(revenue.get("best_selling_units", 0))
        top_product = revenue.get("top_revenue_product")
        top_amount = float(revenue.get("top_revenue_amount", 0.0))
        product_units = revenue.get("product_units") or {}

        unique_customers = int(customers.get("total_unique_customers", 0))
        repeat_customers = int(customers.get("repeat_customers", 0))
        repeat_rate = float(customers.get("repeat_rate", 0.0))
        avg_spend = float(customers.get("average_spending_per_customer", 0.0))
        segment_counts = customers.get("segment_counts") or {}
        spending = customers.get("customer_spending") or {}

        insights: list[dict] = []

        insights.append(
            {
                "title": "Revenue baseline",
                "detail": "The cleaned dataset produced %s orders worth $%s, an average order value of $%s."
                % (orders, format(total_revenue, ",.2f"), format(aov, ",.2f")),
            }
        )

        if by_region:
            top_region = max(by_region, key=by_region.get)
            top_region_revenue = float(by_region[top_region])
            share = round(top_region_revenue / total_revenue * 100, 1) if total_revenue else 0.0
            weakest_region = min(by_region, key=by_region.get)
            insights.append(
                {
                    "title": "Regional concentration",
                    "detail": "%s leads with $%s (%.1f%% of revenue), while %s is weakest at $%s."
                    % (
                        top_region,
                        format(top_region_revenue, ",.2f"),
                        share,
                        weakest_region,
                        format(float(by_region[weakest_region]), ",.2f"),
                    ),
                }
            )

        if best_seller:
            insights.append(
                {
                    "title": "Volume leader",
                    "detail": "%s moves the most units (%s), showing strongest demand at its current price point."
                    % (best_seller, best_units),
                }
            )

        if top_product:
            product_share = round(top_amount / total_revenue * 100, 1) if total_revenue else 0.0
            mismatch = top_product != best_seller
            insights.append(
                {
                    "title": "Revenue driver",
                    "detail": "%s generates the most revenue ($%s, %.1f%% of total)%s."
                    % (
                        top_product,
                        format(top_amount, ",.2f"),
                        product_share,
                        " and differs from the unit-volume leader, indicating a higher price point"
                        if mismatch
                        else "",
                    ),
                }
            )

        if unique_customers:
            insights.append(
                {
                    "title": "Customer loyalty",
                    "detail": "%s of %s customers ordered more than once (%.1f%% repeat rate), with average spend of $%s per customer."
                    % (
                        repeat_customers,
                        unique_customers,
                        repeat_rate * 100,
                        format(avg_spend, ",.2f"),
                    ),
                }
            )

        if segment_counts and spending:
            high_count = int(segment_counts.get("high", 0))
            high_total = sum(
                amount for amount in spending.values() if amount >= float(
                    (customers.get("segment_thresholds") or {}).get("high", 2000)
                )
            )
            high_share = round(high_total / total_revenue * 100, 1) if total_revenue else 0.0
            insights.append(
                {
                    "title": "Spend concentration",
                    "detail": "%s high-value customers contribute $%s, or %.1f%% of total revenue, while %s customers sit in the low-spend segment."
                    % (
                        high_count,
                        format(high_total, ",.2f"),
                        high_share,
                        int(segment_counts.get("low", 0)),
                    ),
                }
            )

        if aov and avg_spend:
            ratio = round(avg_spend / aov, 2)
            insights.append(
                {
                    "title": "Purchase frequency signal",
                    "detail": "Average customer spend is %.2fx the average order value, implying roughly %.1f orders per active customer."
                    % (ratio, ratio),
                }
            )

        if product_units:
            bottom_product = min(product_units, key=product_units.get)
            insights.append(
                {
                    "title": "Underperforming SKU",
                    "detail": "%s is the slowest mover with %s units, a candidate for promotion or delisting."
                    % (bottom_product, product_units[bottom_product]),
                }
            )

        return {"insights": insights}

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

