class Execution:
    name: str = "final_report"
    description: str = "Assembles business insights and data-quality counts into a structured report."
    category: str = "utility"

    inputs: list[dict] = [
        {"name": "insights", "type": list},
        {"name": "rejected_count", "type": float},
    ]

    outputs: list[dict] = [
        {"name": "report", "type": dict},
    ]

    parameters: dict = {}

    def run(self, inputs, parameters, context):
        insights = inputs.get("insights") or []
        rejected = int(inputs.get("rejected_count") or 0)

        titles = [str(item.get("title", "Insight")) for item in insights if isinstance(item, dict)]

        report = {
            "title": "Sales Data Analysis Pipeline - Final Report",
            "sections": {
                "data_quality": {
                    "rejected_records": rejected,
                    "status": "clean" if rejected == 0 else "cleaned_with_rejections",
                    "note": "%s record(s) failed validation and were excluded from analysis." % rejected,
                },
                "executive_summary": "%s business insights were generated from the validated sales data." % len(insights),
                "insights": insights,
                "insight_titles": titles,
            },
            "metrics": {
                "insight_count": len(insights),
                "rejected_count": rejected,
                "analysis_complete": len(insights) >= 5 and rejected >= 0,
            },
        }

        return {"report": report}

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)
